import{G as e,W as t,n,rt as r}from"./chunks/framework.CMPLvzN_.js";var i=JSON.parse(`{"title":"比例倍数问题","description":"","frontmatter":{},"headers":[],"relativePath":"数量关系/比例倍数.md","filePath":"数量关系/比例倍数.md"}`),a={name:`数量关系/比例倍数.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="比例倍数问题" tabindex="-1">比例倍数问题 <a class="header-anchor" href="#比例倍数问题" aria-label="Permalink to “比例倍数问题”">​</a></h1><p>题目中提到几项数据的比值，那么首先其中一项的数量肯定是其所占比值的倍数。</p><blockquote><p>比如男女比例是3:2，那么男生人数一定是3的倍数，女生人数一定是2的倍数。 题型识别：</p></blockquote><ul><li>出现了比例、倍数、分数或百分号%</li></ul><p>如果是出现的百分数，类似于资料分析中求基期现期的数据。那么也可以将其转化为比例倍数问题来解决。</p><p>比如：</p><p>以150元价格售出两张cd，一张盈利25%，一张亏损25%，求总的盈亏情况</p><p>盈利：售价/成本=1.25=5/4，已知售价是150，所以成本是120，+30 亏损：售价/成本=0.75=3/4，已知售价是150，所以成本是200，-50</p><p>所以总亏损20.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};